M_AT = module(
    "mod-audittrail", "ls_audit_trail", "Audit trail", "Piste d'audit",
    [
        ("p", "**ls_audit_trail** records who changed what, when and from where, for the models and fields chosen in "
              "*audit rules*. Each change becomes an immutable entry of a per-company SHA-256 hash chain, so that "
              "altering, inserting or removing an entry is detectable. Integrity is verified on demand and daily by a "
              "scheduled action; *evidence packs* export a sealed ZIP (JSON, CSV and manifest) with its digest for "
              "inspectors; a controlled *retention run* removes aged entries while anchoring the chain. **Nothing is "
              "audited until a rule exists.** One-to-many and many-to-many relations and non-stored computed fields are "
              "never captured directly."),
        ("table", ["Menu", "Content"], [
            ["{{Audit Trail ▸ Audit Log / Field Changes / Audit Dashboard}}", "Entries and field changes"],
            ["{{Audit Trail ▸ Integrity ▸ Verifications / Verify Now}}", "Integrity checks"],
            ["{{Audit Trail ▸ Evidence Packs}}", "Sealed exports"],
            ["{{Audit Trail ▸ Configuration ▸ Audit Rules / Retention Run}}", "Scope and retention"],
        ]),
        ("table", ["Group", "Main rights"], [
            ["Audit Trail / Viewer", "Read the trail of their companies"],
            ["Audit Trail / Auditor", "Also verify integrity and produce evidence packs"],
            ["Audit Trail / Administrator", "Also configure rules and run approved retention"],
        ]),
        ("schematic", "hash_chain", "How the hash chain makes tampering detectable."),
    ],
    [
        ("p", "**ls_audit_trail** enregistre qui a modifié quoi, quand et d'où, pour les modèles et champs choisis dans "
              "des *règles d'audit*. Chaque modification devient une entrée immuable d'une chaîne d'empreintes SHA-256 "
              "par société : modifier, insérer ou supprimer une entrée devient détectable. L'intégrité est vérifiée à la "
              "demande et chaque jour par une action planifiée ; les *dossiers de preuves* exportent une archive ZIP "
              "scellée (JSON, CSV et manifeste) avec son empreinte pour les inspecteurs ; une *purge de conservation* "
              "maîtrisée supprime les entrées anciennes en ancrant la chaîne. **Rien n'est audité tant qu'aucune règle "
              "n'existe.** Les relations un-à-plusieurs et plusieurs-à-plusieurs et les champs calculés non stockés ne "
              "sont jamais capturés directement."),
        ("table", ["Menu", "Contenu"], [
            ["{{Audit Trail ▸ Audit Log / Field Changes / Audit Dashboard}}", "Entrées et modifications de champs"],
            ["{{Audit Trail ▸ Integrity ▸ Verifications / Verify Now}}", "Contrôles d'intégrité"],
            ["{{Audit Trail ▸ Evidence Packs}}", "Exports scellés"],
            ["{{Audit Trail ▸ Configuration ▸ Audit Rules / Retention Run}}", "Périmètre et conservation"],
        ]),
        ("table", ["Groupe", "Droits principaux"], [
            ["Audit Trail / Viewer", "Lecture de la piste de ses sociétés"],
            ["Audit Trail / Auditor", "Vérifie aussi l'intégrité et produit les dossiers de preuves"],
            ["Audit Trail / Administrator", "Paramètre aussi les règles et exécute les purges approuvées"],
        ]),
        ("schematic", "hash_chain", "Comment la chaîne d'empreintes rend la falsification détectable."),
    ],
)

